mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const dir = mkdtempSync(join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = dir;
const bot = await import('<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g3-2/bot.mjs');
const { recordUnsubscribe: unsub, recordResubscribe: resub, mayEmail } = bot;
const d = (s) => new Date(s);
const mkt = (to) => ({ to, kind: 'marketing' });
const tx = (to) => ({ to, kind: 'transactional' });
const now = d('2026-10-22T10:00:00Z');

// Fresh address: marketing allowed, reason null
assert.deepEqual(await mayEmail(mkt('new@example.com'), now), { allowed: true, reason: null });

// Unsubscribe blocks marketing, not transactional
await unsub('Ann@Example.com', d('2026-10-01T00:00:00Z'));
assert.deepEqual(await mayEmail(mkt('ann@example.com'), now), { allowed: false, reason: 'unsubscribed' });
assert.deepEqual(await mayEmail(tx('ann@example.com'), now), { allowed: true, reason: null });

// Header form, mailto, whitespace, plus-alias, gmail dots, googlemail
await unsub('"Bob B" <<EMAIL>>', d('2026-10-01T00:00:00Z'));
for (const to of ['<EMAIL>', ' <EMAIL> ', 'mailto:<EMAIL>', 'Bob <<EMAIL>>']) {
  assert.equal((await mayEmail(mkt(to), now)).reason, 'unsubscribed', to);
}
assert.equal((await mayEmail(mkt('<EMAIL>'), now)).allowed, true);

// Out of order: resubscribe arrives before the unsubscribe it follows
await resub('carl@example.com', d('2026-10-05T00:00:00Z'));
await unsub('carl@example.com', d('2026-10-02T00:00:00Z'));
assert.equal((await mayEmail(mkt('carl@example.com'), now)).allowed, true, 'resub later than unsub clears');

// Resubscribe older than an unsubscribe does not clear it
await unsub('dan@example.com', d('2026-10-09T00:00:00Z'));
await resub('dan@example.com', d('2026-10-03T00:00:00Z'));
assert.equal((await mayEmail(mkt('dan@example.com'), now)).reason, 'unsubscribed');

// Tie: unsubscribe wins
await unsub('eve@example.com', d('2026-10-04T00:00:00Z'));
await resub('eve@example.com', d('2026-10-04T00:00:00Z'));
assert.equal((await mayEmail(mkt('eve@example.com'), now)).reason, 'unsubscribed');

// Re-unsubscribe after resubscribe blocks again
await resub('fay@example.com', d('2026-10-03T00:00:00Z'));
await unsub('fay@example.com', d('2026-10-06T00:00:00Z'));
assert.equal((await mayEmail(mkt('fay@example.com'), now)).reason, 'unsubscribed');

// Unknown kind and invalid recipient fail closed
assert.equal((await mayEmail({ to: 'x@example.com', kind: 'newsletter' }, now)).reason, 'unknown_kind');
assert.equal((await mayEmail(mkt('not-an-address'), now)).reason, 'invalid_recipient');
assert.equal((await mayEmail(mkt('@example.com'), now)).reason, 'invalid_recipient');

// Bad inputs throw
await assert.rejects(unsub('x@example.com', '2026-10-01'), TypeError);
await assert.rejects(unsub('nope', d('2026-10-01')), TypeError);

// Concurrent writers from one process
await Promise.all(Array.from({ length: 50 }, (_, i) => unsub('race@example.com', d(`2026-10-01T00:00:${String(i % 60).padStart(2, '0')}Z`))));
assert.equal((await mayEmail(mkt('race@example.com'), now)).reason, 'unsubscribed');

console.log('in-process checks passed; STATE_DIR =', dir);
EOF
cd /tmp/bot-check && node check.mjs

cd /tmp/bot-check && export STATE_DIR=$(mktemp -d /tmp/bot-mp-XXXX) && BOT=<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g3-2/bot.mjs && for i in $(seq 1 20); do node -e "import('$BOT').then(b=>b.recordUnsubscribe('Multi.User+$<EMAIL>', new Date(Date.UTC(2026,9,1,0,0,$i))))" & done; wait && node -e "
import('$BOT').then(async b=>{
  const now=new Date('2026-10-22T00:00:00Z');
  console.log('after 20 concurrent unsubs:', await b.mayEmail({to:'<EMAIL>',kind:'marketing'},now));
  await b.recordResubscribe('<EMAIL>', new Date('2026-10-10Z'));
  console.log('after later resub (new process):', await b.mayEmail({to:'<EMAIL>',kind:'marketing'},now));
  console.log('transactional still ok:', await b.mayEmail({to:'<EMAIL>',kind:'transactional'},now));
});" && wc -l $STATE_DIR/optouts/* | tail -1; ls $STATE_DIR/optouts | wc -l; rm -rf "$STATE_DIR"; cd <HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/baseline-g3-2 && ls -la
